package com.library.catalogsets;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.*;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;
import java.util.concurrent.*;
import static com.library.catalogattributes.CatalogAttributeSupport.*;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="MYSQL_TEST_URL",matches=".+")
@SpringBootTest(properties={"spring.flyway.enabled=true","spring.sql.init.mode=never","bootstrap.admin.username=admin","bootstrap.admin.password=B34SyntheticAdministrator123","mybatis-plus.configuration.log-impl=org.apache.ibatis.logging.nologging.NoLoggingImpl"})
public class MySqlCatalogSetServiceTest extends CatalogSetServiceTest {
    @DynamicPropertySource static void mysql(DynamicPropertyRegistry r){String url=System.getenv("MYSQL_TEST_URL");if(url==null||!url.matches("jdbc:mysql://[^/]+/library_repair_tests(?:\\?.*)?"))throw new IllegalStateException("Disposable schema only");r.add("spring.datasource.url",()->url);r.add("spring.datasource.driver-class-name",()->"com.mysql.cj.jdbc.Driver");r.add("spring.datasource.username",()->System.getenv().getOrDefault("MYSQL_TEST_USER","root"));r.add("spring.datasource.password",()->System.getenv("MYSQL_TEST_PASSWORD"));}
    @Test void cancelFirstAndConfirmFirstCompeteOnActualMysqlLocks()throws Exception{for(boolean cancelFirst:List.of(true,false)){JsonNode p=preview(create(newMember(book())));CountDownLatch written=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<JsonNode> first=pool.submit(()->new TransactionTemplate(transactions).execute(s->{JsonNode result=cancelFirst?cancel(p,"EDIT"):confirm(p);written.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}return result;}));assertTrue(written.await(5,TimeUnit.SECONDS));Future<String> second=pool.submit(()->{try{JsonNode r=cancelFirst?confirm(p):cancel(p,"EDIT");return r.path("state").asText();}catch(CatalogSetSupport.Failure e){return e.code;}});Thread.sleep(200);assertFalse(second.isDone());release.countDown();first.get(10,TimeUnit.SECONDS);assertEquals(cancelFirst?"PREVIEW_CANCELLED":"COMMITTED",second.get(10,TimeUnit.SECONDS));assertEquals(cancelFirst?0:1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_event WHERE request_id=?",Integer.class,p.path("requestId").asLong()));}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}}
    @Test void legacyWriterFirstInvalidatesConfirmationAndConfirmationFirstPreservesIdentityAtCommit()throws Exception{for(boolean writerFirst:List.of(true,false)){long b=book();JsonNode p=preview(create(newMember(b)));CountDownLatch written=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> first=pool.submit(()->{authenticate();try{return new TransactionTemplate(transactions).execute(s->{if(writerFirst)metadata(b,"title","合成先写身份"+b);else confirm(p);written.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}return null;});}finally{clear();}});assertTrue(written.await(5,TimeUnit.SECONDS));Future<String> second=pool.submit(()->{authenticate();try{if(writerFirst){try{confirm(p);return "COMMITTED";}catch(CatalogSetSupport.Failure e){return e.code;}}metadata(b,"title","合成后写身份"+b);return "WRITTEN";}finally{clear();}});Thread.sleep(200);assertFalse(second.isDone());release.countDown();first.get(10,TimeUnit.SECONDS);assertEquals(writerFirst?"BOOK_IDENTITY_CHANGED":"WRITTEN",second.get(10,TimeUnit.SECONDS));assertEquals(writerFirst?0:1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_set_event WHERE request_id=?",Integer.class,p.path("requestId").asLong()));}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}}
    @Test void busyMutexKeepsOriginalKeyRecoverable()throws Exception{JsonNode n=create();CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newSingleThreadExecutor();try{Future<?> locker=pool.submit(()->new TransactionTemplate(transactions).execute(s->{service.lock();held.countDown();try{release.await(12,TimeUnit.SECONDS);}catch(InterruptedException e){throw new RuntimeException(e);}return null;}));assertTrue(held.await(5,TimeUnit.SECONDS));reason("CATALOG_BUSY",()->preview(n));release.countDown();locker.get(10,TimeUnit.SECONDS);JsonNode p=preview(n);assertEquals(p,service.byKey(q("key",n.path("operationKey").asText()),admin));confirm(p);}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
    @Test void sameSetCompetingPreviewsCommitOnlyOne()throws Exception{long s=set();JsonNode p=preview(operation("RETIRE_SET",s)),t=preview(operation("RETIRE_SET",s));ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<String> x=pool.submit(()->outcome(p)),y=pool.submit(()->outcome(t));List<String> results=List.of(x.get(15,TimeUnit.SECONDS),y.get(15,TimeUnit.SECONDS));assertEquals(1,results.stream().filter("COMMITTED"::equals).count());assertEquals(1,results.stream().filter("CATALOG_SET_CHANGED"::equals).count());}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
    @Test void sourcePaginationHasConstantQueryBudgetAndExplainPlan()throws Exception{List<Long> ids=new ArrayList<>();for(int i=0;i<25;i++){long id=book();ids.add(id);source(id,sourceCopy(id),"{\"套装类型\":\"套装中单本\"}");}SelectCounterDataSource counter=new SelectCounterDataSource(jdbc.getDataSource());var counted=new CatalogSetService(new org.springframework.jdbc.core.JdbcTemplate(counter),new org.springframework.jdbc.datasource.DataSourceTransactionManager(counter));Map<String,Object> result=new LinkedHashMap<>();for(int size:List.of(1,20)){counter.sql.clear();JsonNode r=counted.reviews(q("size",""+size),admin);assertTrue(r.path("total").asLong()>=25);assertTrue(counter.sql.size()<=5,"case SELECT count="+counter.sql.size());result.put("listSize"+size,obj("selects",counter.sql.size(),"total",r.get("total"),"records",r.path("records").size()));}counter.sql.clear();var params=q();for(long id:ids)params.add("bookId",""+id);assertEquals(25,counted.bookContexts(params,admin).path("records").size());assertTrue(counter.sql.size()<=4);result.put("contexts25Selects",counter.sql.size());counter.sql.clear();JsonNode detail=counted.sourceDetails(q("caseKey","SET_SOURCE_BOOK:"+ids.get(0),"size","1"),admin);assertEquals(1,detail.path("total").asLong());assertTrue(counter.sql.size()<=4);result.put("sourcesSelects",counter.sql.size());result.put("explain",jdbc.queryForObject("EXPLAIN FORMAT=JSON "+service.sources.cte()+"SELECT * FROM cases WHERE has_marker=1 AND deleted=0 ORDER BY case_book LIMIT 20",String.class));String dir=System.getProperty("b34.evidence.dir");if(dir!=null)java.nio.file.Files.writeString(java.nio.file.Path.of(dir,"source-query-budget-and-explain.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(result));}
    @Test void deleteAndPreviewBothLockOrdersKeepReferencesAndIdentitySafe()throws Exception{for(boolean previewFirst:List.of(true,false)){long b=book();JsonNode n=create(newMember(b));CountDownLatch written=new CountDownLatch(1),release=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> first=pool.submit(()->{authenticate();try{return new TransactionTemplate(transactions).execute(s->{if(previewFirst)preview(n);else books.delete(b);written.countDown();try{assertTrue(release.await(10,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}return null;});}finally{clear();}});assertTrue(written.await(5,TimeUnit.SECONDS));Future<String> second=pool.submit(()->{authenticate();try{if(previewFirst)books.delete(b);else preview(n);return "UNEXPECTED_SUCCESS";}catch(CatalogSetSupport.Failure e){return e.code;}finally{clear();}});Thread.sleep(200);assertFalse(second.isDone());release.countDown();first.get(10,TimeUnit.SECONDS);assertEquals(previewFirst?"CATALOG_SET_REFERENCED":"BOOK_NOT_FOUND",second.get(10,TimeUnit.SECONDS));assertEquals(previewFirst?0:1,jdbc.queryForObject("SELECT catalog_set_book_revision FROM book WHERE id=?",Long.class,b));}finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}}
    @Test void maintenanceMemberPagesUseAtMostFourSelectsAcrossSizesAndHistoricalCases()throws Exception{List<JsonNode> rows=new ArrayList<>();for(int i=0;i<25;i++){long b=book();source(b,sourceCopy(b),"{\"套装类型\":\"套装中单本\"}");rows.add(newMember(b));}long withSources=confirm(preview(create(rows.toArray(JsonNode[]::new)))).path("result").path("set").path("setId").asLong();long withoutSources=confirm(preview(create(newMember(book()),newMember(book()),newMember(book())))).path("result").path("set").path("setId").asLong();long deletedBook=book();source(deletedBook,sourceCopy(deletedBook),"{\"套装类型\":\"套装中单本\"}");long historical=confirm(preview(create(newMember(deletedBook)))).path("result").path("set").path("setId").asLong();confirm(preview(members("RETIRE_MEMBERS",historical,existing(historical,deletedBook))));jdbc.update("UPDATE book SET deleted=1 WHERE id=?",deletedBook);long emptySet=set();SelectCounterDataSource counter=new SelectCounterDataSource(jdbc.getDataSource());var counted=new CatalogSetService(new org.springframework.jdbc.core.JdbcTemplate(counter),new org.springframework.jdbc.datasource.DataSourceTransactionManager(counter));Map<String,Object> evidence=new LinkedHashMap<>();for(int size:List.of(1,20)){for(String scenario:List.of("withSources","withoutSources","deletedHistorical","emptySet","pastLastPage","missingSet")){long target=switch(scenario){case "withSources","pastLastPage"->withSources;case "withoutSources"->withoutSources;case "deletedHistorical"->historical;case "emptySet"->emptySet;default->CatalogSetSupport.MAX;};var params=q("size",""+size,"status",scenario.equals("deletedHistorical")?"RETIRED":"ALL");if(scenario.equals("pastLastPage"))params.add("page","999");counter.sql.clear();if(scenario.equals("missingSet")){reason("SET_NOT_FOUND",()->counted.members(target,params,admin,true,false));assertEquals(1,counter.sql.size());evidence.put(scenario+"-size"+size,obj("selects",counter.sql.size(),"status",404,"reasonCode","SET_NOT_FOUND","sql",counter.sql));continue;}JsonNode page=counted.members(target,params,admin,true,false);int expected=scenario.equals("withSources")||scenario.equals("deletedHistorical")?4:scenario.equals("withoutSources")?3:2;assertEquals(expected,counter.sql.size(),scenario+" size="+size);assertTrue(counter.sql.size()<=4);long expectedTotal=scenario.equals("withSources")||scenario.equals("pastLastPage")?25:scenario.equals("withoutSources")?3:scenario.equals("deletedHistorical")?1:0;assertEquals(expectedTotal,page.path("total").asLong());if(scenario.equals("pastLastPage")||scenario.equals("emptySet"))assertTrue(page.path("records").isEmpty());else assertEquals(Math.min(size,expectedTotal),page.path("records").size());for(JsonNode row:page.path("records")){assertEquals(row.path("member").get("bookId"),row.path("book").path("book").get("bookId"));assertEquals(hash(obj("schemaVersion",1,"book",row.path("book").path("book"))),row.path("book").path("bookDigest").asText());if(scenario.equals("withoutSources"))assertEquals("NO_SOURCE",row.path("book").path("source").path("markerState").asText());if(scenario.equals("deletedHistorical")){assertTrue(row.path("book").path("book").path("deleted").asBoolean());assertEquals("RETIRED",row.path("member").path("status").asText());assertEquals("ASSOCIATION_INVALID",row.path("book").path("source").path("associationState").asText());}}evidence.put(scenario+"-size"+size,obj("selects",counter.sql.size(),"total",page.get("total"),"records",page.path("records").size(),"sql",new ArrayList<>(counter.sql)));}}String dir=System.getProperty("b34.evidence.dir");if(dir!=null)java.nio.file.Files.writeString(java.nio.file.Path.of(dir,"maintenance-members-query-budget.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obj("synthetic",true,"transport","actual executed SELECTs on MySQL via CatalogSetService maintenance route", "maxSelects",4,"matrix",evidence)));}
    String outcome(JsonNode p){try{confirm(p);return "COMMITTED";}catch(CatalogSetSupport.Failure e){return e.code;}}
}
